class TreeNode(var `val`: Int) {
    var left: TreeNode? = null
    var right: TreeNode? = null
}

fun searchBST(root: TreeNode?, target: Int): TreeNode? {
    var node = root
    while (node != null && node.`val` != target) {
        node = if (target < node.`val`) node.left else node.right
    }
    return node
}
// Time: O(h)   Space: O(1)

fun insertIntoBST(root: TreeNode?, value: Int): TreeNode {
    if (root == null) return TreeNode(value)
    if (value < root.`val`) root.left = insertIntoBST(root.left, value)
    else root.right = insertIntoBST(root.right, value)
    return root
}
// Time: O(h)   Space: O(h) recursion

fun deleteNode(root: TreeNode?, key: Int): TreeNode? {
    if (root == null) return null
    when {
        key < root.`val` -> root.left = deleteNode(root.left, key)
        key > root.`val` -> root.right = deleteNode(root.right, key)
        else -> {
            // case 1 and 2: zero or one child
            if (root.left == null) return root.right
            if (root.right == null) return root.left
            // case 3: two children, copy the inorder successor, then delete it
            var successor = root.right!!
            while (successor.left != null) successor = successor.left!!
            root.`val` = successor.`val`
            root.right = deleteNode(root.right, successor.`val`)
        }
    }
    return root
}
// Time: O(h)   Space: O(h)

fun isValidBST(root: TreeNode?): Boolean {
    fun check(node: TreeNode?, low: Long, high: Long): Boolean {
        if (node == null) return true
        if (node.`val` <= low || node.`val` >= high) return false
        return check(node.left, low, node.`val`.toLong()) &&
               check(node.right, node.`val`.toLong(), high)
    }
    return check(root, Long.MIN_VALUE, Long.MAX_VALUE)
}
// Time: O(n)   Space: O(h)
// Every node must fit inside a (low, high) window inherited from its ancestors

fun inorder(root: TreeNode?): List<Int> {
    val result = mutableListOf<Int>()
    val stack = ArrayDeque<TreeNode>()
    var curr = root
    while (curr != null || stack.isNotEmpty()) {
        while (curr != null) {
            stack.addLast(curr)
            curr = curr.left
        }
        val node = stack.removeLast()
        result.add(node.`val`)
        curr = node.right
    }
    return result
}
// Time: O(n)   Space: O(h)
// For a valid BST the output is strictly increasing

fun isValidBSTInorder(root: TreeNode?): Boolean {
    val stack = ArrayDeque<TreeNode>()
    var curr = root
    var prev: Int? = null
    while (curr != null || stack.isNotEmpty()) {
        while (curr != null) {
            stack.addLast(curr)
            curr = curr.left
        }
        val node = stack.removeLast()
        if (prev != null && node.`val` <= prev) return false   // must be strictly increasing
        prev = node.`val`
        curr = node.right
    }
    return true
}
// Time: O(n)   Space: O(h)

fun kthSmallest(root: TreeNode?, k: Int): Int {
    val stack = ArrayDeque<TreeNode>()
    var curr = root
    var remaining = k
    while (curr != null || stack.isNotEmpty()) {
        while (curr != null) {
            stack.addLast(curr)
            curr = curr.left
        }
        val node = stack.removeLast()
        remaining--
        if (remaining == 0) return node.`val`        // stop early
        curr = node.right
    }
    return -1
}
// Time: O(h + k)   Space: O(h)
// For frequent queries, store subtree sizes in each node to answer in O(h)

fun lowestCommonAncestor(root: TreeNode?, p: TreeNode, q: TreeNode): TreeNode? {
    var node = root
    while (node != null) {
        node = when {
            p.`val` < node.`val` && q.`val` < node.`val` -> node.left     // both on the left
            p.`val` > node.`val` && q.`val` > node.`val` -> node.right    // both on the right
            else -> return node                                           // split point
        }
    }
    return null
}
// Time: O(h)   Space: O(1)

fun sortedArrayToBST(nums: IntArray): TreeNode? {
    fun build(left: Int, right: Int): TreeNode? {
        if (left > right) return null
        val mid = left + (right - left) / 2
        val node = TreeNode(nums[mid])               // middle becomes the root
        node.left = build(left, mid - 1)
        node.right = build(mid + 1, right)
        return node
    }
    return build(0, nums.size - 1)
}
// Time: O(n)   Space: O(log n)

fun inorderSuccessor(root: TreeNode?, p: TreeNode): TreeNode? {
    var successor: TreeNode? = null
    var node = root
    while (node != null) {
        if (p.`val` < node.`val`) {
            successor = node                         // candidate: a bigger value
            node = node.left
        } else {
            node = node.right
        }
    }
    return successor
}
// Time: O(h)   Space: O(1)
// Predecessor: mirror the logic (use p.val > node.val and move right)

fun rangeSumBST(root: TreeNode?, low: Int, high: Int): Int {
    if (root == null) return 0
    if (root.`val` < low) return rangeSumBST(root.right, low, high)    // left subtree is too small
    if (root.`val` > high) return rangeSumBST(root.left, low, high)    // right subtree is too big
    return root.`val` +
        rangeSumBST(root.left, low, high) +
        rangeSumBST(root.right, low, high)
}
// Time: O(n) worst case, less with pruning   Space: O(h)

fun trimBST(root: TreeNode?, low: Int, high: Int): TreeNode? {
    if (root == null) return null
    if (root.`val` < low) return trimBST(root.right, low, high)        // discard node and left subtree
    if (root.`val` > high) return trimBST(root.left, low, high)        // discard node and right subtree
    root.left = trimBST(root.left, low, high)
    root.right = trimBST(root.right, low, high)
    return root
}
// Time: O(n)   Space: O(h)

fun findTarget(root: TreeNode?, k: Int): Boolean {
    val values = ArrayList<Int>()

    fun inorder(node: TreeNode?) {
        if (node == null) return
        inorder(node.left)
        values.add(node.`val`)
        inorder(node.right)
    }

    inorder(root)                                    // sorted list
    var l = 0
    var r = values.size - 1
    while (l < r) {
        val sum = values[l] + values[r]
        when {
            sum == k -> return true
            sum < k -> l++
            else -> r--
        }
    }
    return false
}
// Time: O(n)   Space: O(n)
// A forward and a backward BSTIterator can do this in O(h) space

fun getMinimumDifference(root: TreeNode?): Int {
    var best = Int.MAX_VALUE
    var prev: Int? = null

    fun inorder(node: TreeNode?) {
        if (node == null) return
        inorder(node.left)
        prev?.let { best = minOf(best, node.`val` - it) }   // closest values are neighbors in order
        prev = node.`val`
        inorder(node.right)
    }

    inorder(root)
    return best
}
// Time: O(n)   Space: O(h)

class BSTIterator(root: TreeNode?) {
    private val stack = ArrayDeque<TreeNode>()

    init {
        pushLeft(root)
    }

    private fun pushLeft(node: TreeNode?) {
        var cur = node
        while (cur != null) {
            stack.addLast(cur)
            cur = cur.left
        }
    }

    fun next(): Int {
        val node = stack.removeLast()
        pushLeft(node.right)
        return node.`val`
    }

    fun hasNext(): Boolean = stack.isNotEmpty()
}
// next(): O(1) amortized   Space: O(h)

fun recoverTree(root: TreeNode?) {
    var first: TreeNode? = null
    var second: TreeNode? = null
    var prev: TreeNode? = null

    fun inorder(node: TreeNode?) {
        if (node == null) return
        inorder(node.left)
        val p = prev
        if (p != null && p.`val` > node.`val`) {      // order violation
            if (first == null) first = p              // first violation: earlier node
            second = node                             // last violation: later node
        }
        prev = node
        inorder(node.right)
    }

    inorder(root)
    val a = first
    val b = second
    if (a != null && b != null) {
        val tmp = a.`val`
        a.`val` = b.`val`
        b.`val` = tmp
    }
}
// Time: O(n)   Space: O(h)
// Swapped nodes show up as one or two places where the inorder sequence decreases

import kotlin.math.abs

fun closestValue(root: TreeNode?, target: Double): Int {
    var closest = root!!.`val`
    var node: TreeNode? = root
    while (node != null) {
        if (abs(node.`val` - target) < abs(closest - target)) closest = node.`val`
        node = if (target < node.`val`) node.left else node.right
    }
    return closest
}
// Time: O(h)   Space: O(1)

fun convertBST(root: TreeNode?): TreeNode? {
    var sum = 0

    fun reverseInorder(node: TreeNode?) {
        if (node == null) return
        reverseInorder(node.right)                    // largest values first
        sum += node.`val`
        node.`val` = sum
        reverseInorder(node.left)
    }

    reverseInorder(root)
    return root
}
// Time: O(n)   Space: O(h)

fun bstFromPreorder(preorder: IntArray): TreeNode? {
    var idx = 0

    fun build(upperBound: Int): TreeNode? {
        if (idx == preorder.size || preorder[idx] > upperBound) return null
        val node = TreeNode(preorder[idx++])
        node.left = build(node.`val`)                 // left values must be below the node
        node.right = build(upperBound)                // right values must be below the inherited bound
        return node
    }

    return build(Int.MAX_VALUE)
}
// Time: O(n)   Space: O(h)

fun numTrees(n: Int): Int {
    val dp = IntArray(n + 2)
    dp[0] = 1
    dp[1] = 1
    for (nodes in 2..n) {
        for (root in 1..nodes) {
            // root has (root - 1) smaller values on the left and (nodes - root) larger on the right
            dp[nodes] += dp[root - 1] * dp[nodes - root]
        }
    }
    return dp[n]
}
// Time: O(n²)   Space: O(n)
